/* Build 205 — normalized knowledge foundation.
 * This layer deliberately preserves the legacy error/message arrays above so the
 * current application can continue to use them unchanged. New code should prefer
 * CW_KNOWLEDGE_BASE.records and CW_KNOWLEDGE_BASE.parts once those records are
 * source-validated. No part description is inferred here.
 */
(function(){
  const db=window.CW_MANUAL_DATABASE || {};
  const sourceId=db.databaseId || "hp-e52645";
  const modelId=db.model || "E52645";

  const normalizeCode = v => String(v ?? "").trim();
  const normalizeText = v => String(v ?? "").replace(/\s+/g," ").trim();
  // Technician-only normalization: preserve the original legacy database above,
  // but remove customer/call-center routing text from the normalized diagnostic layer.
  const normalizeTechnicianStep = v => {
    let t = normalizeText(v);
    if (!t) return "";
    // If a whole extracted step is explicitly a customer-only routing line,
    // omit it. Otherwise remove routing labels/page artifacts without deleting
    // surrounding technician instructions (PDF extraction can place the label mid-sentence).
    if (/^Recommended action for customers?\b/i.test(t)) return "";
    t = t.replace(/Recommended action for (?:call-center agents?|customers?)(?:\s+and\s+onsite technicians?)?(?:\s+\d{1,3})?\b/gi, "");
    t = t.replace(/\bFollow these troubleshooting steps in the order presented\.?/gi, "");
    t = t.replace(/\s{2,}/g, " ").trim();
    // Remove a page number that was attached directly to a routing label.
    t = t.replace(/\s+(?=\d{1,3}\b)/g, " ");
    return t;
  };

  const errors=(Array.isArray(db.errors)?db.errors:[]).map((x,i)=>({
    id:`${sourceId}:error:${i+1}`,
    type:"error",
    model:modelId,
    code:normalizeCode(x.code),
    officialDescription:normalizeText(x.desc),
    summary:Array.isArray(x.summary)?x.summary.map(normalizeText).filter(Boolean):[],
    troubleshootingSteps:Array.isArray(x.steps)?x.steps.map(normalizeTechnicianStep).filter(Boolean):[],
    sourceId,
    sourceStatus:"legacy-import-pending-validation"
  }));

  const messages=(Array.isArray(db.messages)?db.messages:[]).map((x,i)=>({
    id:`${sourceId}:message:${i+1}`,
    type:"message",
    model:modelId,
    code:normalizeCode(x.code),
    message:normalizeText(x.message),
    description:normalizeText(x.description),
    actions:Array.isArray(x.actions)?x.actions.map(normalizeTechnicianStep).filter(Boolean):[],
    sourceId,
    sourceStatus:"legacy-import-pending-validation"
  }));

  // Build 207: only parts already explicitly identified in the current E52645
  // service/parts data are promoted into the authoritative layer. No descriptions
  // are inferred from part numbers.
  const parts=[
    {id:`${sourceId}:part:F2A76-67909`,partNumber:"F2A76-67909",displayDescription:"Image scanner assembly kit",type:"kit",models:["M527","E52545","M528","E52645"],sourceTerminology:"Image scanner assembly kit (M527/E52545/M528/E52645)",sourceId,sourceStatus:"verified-source-supported"},
    {id:`${sourceId}:part:B5L47-67018`,partNumber:"B5L47-67018",displayDescription:"Control panel kit",type:"kit",models:["M527","E52545","M528","E52645"],sourceTerminology:"Control panel kit (M527/E52545/M528/E52645)",sourceId,sourceStatus:"verified-source-supported"},
    {id:`${sourceId}:part:B5L47-67019`,partNumber:"B5L47-67019",displayDescription:"Keyboard US",type:"assembly",models:["M527","E52545","M528","E52645"],sourceTerminology:"Keyboard US (M527/E52545/M528/E52645)",sourceId,sourceStatus:"verified-source-supported"},
    {id:`${sourceId}:part:B5L47-67020`,partNumber:"B5L47-67020",displayDescription:"Keyboard UK",type:"assembly",models:["M527","E52545","M528","E52645"],sourceTerminology:"Keyboard UK (M527/E52545/M528/E52645)",sourceId,sourceStatus:"verified-source-supported"},
    {id:`${sourceId}:part:B5L46-40021`,partNumber:"B5L46-40021",displayDescription:"Cover, HIP",type:"cover",models:["M527","E52545","M528","E52645"],sourceTerminology:"Cover, HIP (M527/E52545/M528/E52645)",sourceId,sourceStatus:"verified-source-supported"},
    {id:`${sourceId}:part:B5L46-60117`,partNumber:"B5L46-60117",displayDescription:"Bezel, control panel",type:"cover",models:["M527","E52545","M528","E52645"],sourceTerminology:"Bezel, control panel (M527/E52545/M528/E52645)",sourceId,sourceStatus:"verified-source-supported"},
    {id:`${sourceId}:part:B5L46-40002`,partNumber:"B5L46-40002",displayDescription:"Cover, keyboard",type:"cover",models:["M527","E52545","M528","E52645"],sourceTerminology:"Cover, keyboard (M527/E52545/M528/E52645)",sourceId,sourceStatus:"verified-source-supported"},
    {id:`${sourceId}:part:5851-5939`,partNumber:"5851-5939",displayDescription:"Cable, WU USB control panel",type:"cable",models:["M527","E52545"],sourceTerminology:"Cable, WU USB control panel (M527/E52545)",sourceId,sourceStatus:"verified-source-supported"},
    {id:`${sourceId}:part:5851-5938`,partNumber:"5851-5938",displayDescription:"Cable, HIP USB control panel",type:"cable",models:["M527","E52545","M528","E52645"],sourceTerminology:"Cable, HIP USB control panel (M527/E52545/M528/E52645)",sourceId,sourceStatus:"verified-source-supported"},
    {id:`${sourceId}:part:5851-5936`,partNumber:"5851-5936",displayDescription:"Cable, HDMI control panel",type:"cable",models:["M527","E52545","M528","E52645"],sourceTerminology:"Cable, HDMI control panel (M527/E52545/M528/E52645)",sourceId,sourceStatus:"verified-source-supported"},
    {id:`${sourceId}:part:5851-5935`,partNumber:"5851-5935",displayDescription:"Cable, 18-pin control panel",type:"cable",models:["M527","E52545","M528","E52645"],sourceTerminology:"Cable, 18-pin control panel (M527/E52545/M528/E52645)",sourceId,sourceStatus:"verified-source-supported"},
    {id:`${sourceId}:part:F2A76-50004`,partNumber:"F2A76-50004",displayDescription:"Cable, HDMI PAB to SCAM",type:"cable",models:["M527","E52545","M528","E52645"],sourceTerminology:"Cable, HDMI PAB to SCAM (M527/E52545/M528/E52645)",sourceId,sourceStatus:"verified-source-supported"},
    {id:`${sourceId}:part:COM39-60064`,partNumber:"COM39-60064",displayDescription:"Hinge, left document feeder",type:"hinge",models:["M527","E52545","M528","E52645"],sourceTerminology:"Hinge, left document feeder (M527/E52545/M528/E52645)",sourceId,sourceStatus:"verified-source-supported"},
    {id:`${sourceId}:part:COM39-60065`,partNumber:"COM39-60065",displayDescription:"Hinge, right document feeder",type:"hinge",models:["M527","E52545","M528","E52645"],sourceTerminology:"Hinge, right document feeder (M527/E52545/M528/E52645)",sourceId,sourceStatus:"verified-source-supported"},
    {id:`${sourceId}:part:B5L46-40028`,partNumber:"B5L46-40028",displayDescription:"Cover, USB",type:"cover",models:["M527","E52545"],sourceTerminology:"Cover, USB (M527/E52545)",sourceId,sourceStatus:"verified-source-supported"},
    {id:`${sourceId}:part:B5L46-40011`,partNumber:"B5L46-40011",displayDescription:"Cover, rear image scanner",type:"cover",models:["M527","E52545"],sourceTerminology:"Cover, rear image scanner (M527/E52545)",sourceId,sourceStatus:"verified-source-supported"},
    {id:`${sourceId}:part:B5L47-67903`,partNumber:"B5L47-67903",displayDescription:"Scan-control board (SCB) kit",type:"kit",models:["M527","E52545"],sourceTerminology:"Scan-control board (SCB) kit (M527/E52545)",sourceId,sourceStatus:"verified-source-supported"},
    {
      id:`${sourceId}:part:B5L47-67906`,
      partNumber:"B5L47-67906",
      displayDescription:"Document feeder whole unit (Enterprise)",
      type:"whole_unit",
      models:["E52545","E52645"],
      sourceTerminology:"Document feeder kit / ADF whole unit",
      sourceId,
      sourceStatus:"verified-source-supported"
    },
    {
      id:`${sourceId}:part:B5L47-67907`,
      partNumber:"B5L47-67907",
      displayDescription:"Document feeder whole unit (Flow)",
      type:"whole_unit",
      models:["E52545","E52645"],
      sourceTerminology:"Document feeder kit / ADF whole unit",
      sourceId,
      sourceStatus:"verified-source-supported"
    },
    {
      id:`${sourceId}:part:RM2-5715-000CN`,
      partNumber:"RM2-5715-000CN",
      displayDescription:"Paper feed drive assembly",
      type:"assembly",
      models:["E52645"],
      sourceId,
      sourceStatus:"verified-current-data"
    },
    {
      id:`${sourceId}:part:RM2-2577-000CN`,
      partNumber:"RM2-2577-000CN",
      displayDescription:"Registration assembly",
      type:"assembly",
      models:["E52645"],
      sourceId,
      sourceStatus:"verified-current-data"
    }
  ];

  window.CW_KNOWLEDGE_BASE={
    schemaVersion:2,
    databaseId:sourceId,
    model:modelId,
    sources:[{
      id:sourceId,
      model:modelId,
      title:"Existing indexed E52645 service-manual data",
      status:"imported",
      notes:"Legacy content preserved for compatibility; normalized records require source validation before becoming authoritative."
    }],
    models:[{
      id:modelId,
      displayName:"HP E52645",
      status:"active-test-model",
      sourceId
    }],
    records:[...errors,...messages],
    errors,
    messages,
    parts,
    relationships:[],
    validation:{
      rules:[
        "Every authoritative part description must have a source reference.",
        "A part description must not be inferred from a part number alone.",
        "A part may not have conflicting authoritative descriptions for the same model.",
        "Troubleshooting content may reference only source-validated authoritative parts when promoted to the normalized layer."
      ],
      status:"foundation-only"
    }
  };

  window.CW_KNOWLEDGE_BASE.getError = function(code){
    const c=normalizeCode(code);
    return this.errors.find(x=>x.code===c) || null;
  };
  window.CW_KNOWLEDGE_BASE.getMessage = function(code){
    const c=normalizeCode(code);
    return this.messages.find(x=>x.code===c) || null;
  };
  window.CW_KNOWLEDGE_BASE.getPart = function(partNumber,model){
    const pn=normalizeCode(partNumber).toUpperCase();
    return this.parts.find(x=>String(x.partNumber).toUpperCase()===pn && (!model || !x.models?.length || x.models.includes(model))) || null;
  };
})();


/* Build 240 — manual-ingestion readiness contract.
 * This does not alter HP troubleshooting content. It defines the normalized
 * fields future manual imports must provide and audits imported records so
 * malformed extraction can be caught before it reaches the technician UI.
 * Validation is record-type-aware: message records do not require an error code.
 */
(function(){
  const kb=window.CW_KNOWLEDGE_BASE;
  if(!kb) return;
  kb.importContract={
    schemaVersion:3,
    requiredRecordFields:["id","type","model","code","sourceId"],
    errorFields:["officialDescription","summary","troubleshootingSteps"],
    messageFields:["message","description","actions"],
    partFields:["partNumber","displayDescription","type","models","sourceId","sourceStatus"],
    supportedRecordTypes:["error","message","part"],
    decisionRule:"Only create a decision from an explicit documented condition; never invent a branch.",
    partRule:"Promote a part only when its number, description, and applicability are supported by the HP source."
  };

  const looksTruncated=t=>{
    t=String(t||"").trim();
    if(!t) return false;
    return /\b(and|or|the|a|an|to|for|with|from|between|on|of|at|in|all|any|following|customer|scanner|control|cable|part)\s*$/i.test(t);
  };
  const audit=[];
  const warnings=[];
  (kb.records||[]).forEach(r=>{
    const issues=[];
    const required = r.type === "error"
      ? ["id","type","model","code","sourceId"]
      : r.type === "message"
        ? ["id","type","model","sourceId"]
        : ["id","type","model","sourceId"];
    required.forEach(f=>{
      if(r[f]===undefined||r[f]===null||String(r[f]).trim()==="") issues.push(`missing:${f}`);
    });
    const steps=r.type==="error"?(r.troubleshootingSteps||[]):r.type==="message"?(r.actions||[]):[];
    steps.forEach((step,i)=>{
      if(looksTruncated(step)) warnings.push({id:r.id,code:r.code,type:r.type,issue:`possible-truncation:step-${i+1}`});
      if(/Recommended action for call-center agents/i.test(step)) warnings.push({id:r.id,code:r.code,type:r.type,issue:`mixed-audience:step-${i+1}`});
    });
    if(issues.length) audit.push({id:r.id,code:r.code,type:r.type,issues});
  });
  // Parts are audited separately because they are authoritative entities, not
  // diagnostic/message records and therefore are not part of kb.records.
  (kb.parts||[]).forEach(p=>{
    const issues=[];
    ["id","partNumber","displayDescription","type","models","sourceId","sourceStatus"].forEach(f=>{
      if(p[f]===undefined||p[f]===null||(Array.isArray(p[f]) ? p[f].length===0 : String(p[f]).trim()==="")) issues.push(`missing:${f}`);
    });
    if(issues.length) audit.push({id:p.id,partNumber:p.partNumber,type:"part",issues});
  });
  kb.importAudit={
    build:241,
    checkedRecords:(kb.records||[]).length+(kb.parts||[]).length,
    flaggedRecords:audit.length,
    findings:audit,
    warningCount:warnings.length,
    warnings,
    status:audit.length?"review-required":(warnings.length?"review-warnings":"pass")
  };
})();


/* Build 239: normalized knowledge-package contract.
 * This layer does not infer troubleshooting logic or part applicability.
 * It preserves the existing source-derived arrays while giving the future
 * manual-ingestion pipeline a stable package shape to validate against.
 */
(function(){
  const db=window.CW_MANUAL_DATABASE||{};
  const clean=v=>String(v==null?"":v).replace(/\s+/g," ").trim();
  const toErrorRecord=e=>({
    recordType:"error",
    id:"error:"+clean(e?.code).toUpperCase(),
    code:clean(e?.code),
    title:clean(e?.desc),
    summary:Array.isArray(e?.summary)?e.summary.map(clean).filter(Boolean):[],
    steps:Array.isArray(e?.steps)?e.steps.map(clean).filter(Boolean):[],
    partsMentioned:Array.isArray(e?.parts)?e.parts.map(clean).filter(Boolean):[],
    sourceRecord:e
  });
  const toMessageRecord=e=>({
    recordType:"message",
    id:"message:"+clean(e?.message).toLowerCase(),
    message:clean(e?.message),
    description:clean(e?.description),
    actions:Array.isArray(e?.actions)?e.actions.map(clean).filter(Boolean):[],
    sourceRecord:e
  });
  window.CW_KNOWLEDGE_PACKAGE={
    schemaVersion:2,
    packageType:"copier-wizard-knowledge",
    packageId:clean(db.databaseId)||"unknown",
    manufacturer:"HP",
    source:{
      model:clean(db.model),
      sourceDescription:clean(db.source),
      authority:"HP service-manual / CPMD source data only"
    },
    records:{
      errors:Array.isArray(db.errors)?db.errors.map(toErrorRecord):[],
      messages:Array.isArray(db.messages)?db.messages.map(toMessageRecord):[]
    },
    legacyDatabase:db
  };
})();
